// 2025-26 C++. Do not edit. Checks that this crate reads the Motor-Pi's
// bytes, and sends the devices the targets, as the C++ did.

use legacy_link::{
    DriveMode, Flags, Frame, FrameError, FrameV2, ModeSwitch, Parser, ParserV2, Sticks, Targets,
    Throttle, Uplink,
};

#[test]
fn stand_still() {
    // to_legacy(0.0, 0.0)
    let bytes = [
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x9a, 0x99, 0x99, 0xbe, 0x8a,
    ];
    let frame = Frame::decode(&bytes).expect("checksum");
    let frame = frame.check().expect("in range");
    assert_eq!(
        frame.targets(),
        Targets {
            steering: 1950,
            brake: 1050,
            throttle: Throttle::Cut
        }
    );
    assert_eq!(frame.encode(), bytes);
}

