#[test]
fn a_stream_with_noise() {
    let stream = [
        0x00, 0xff, 0x13, 0xcd, 0xcc, 0xcc, 0x3d, 0xcd, 0xcc, 0x4c, 0x3e, 0x00, 0x00, 0x00, 0x00,
        0xc5, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80, 0xbf, 0xfe, 0x00, 0x00, 0x00, 0x00, 0xcd, 0xcc,
        0xcc, 0x3e, 0x00, 0x00, 0x00, 0x00, 0xa3, 0xcd, 0xcc, 0x4c, 0x3e, 0x9a, 0x99, 0x99, 0xbe,
        0x00, 0x00, 0x00, 0x00, 0xad,
    ];
    let mut parser = Parser::new();
    let found: Vec<[u8; 13]> = stream
        .iter()
        .filter_map(|&b| parser.push(b))
        .filter_map(Result::ok)
        .map(|f| f.encode())
        .collect();
    let expected: Vec<[u8; 13]> = vec![
        [
            0xcd, 0xcc, 0xcc, 0x3d, 0xcd, 0xcc, 0x4c, 0x3e, 0x00, 0x00, 0x00, 0x00, 0xc5,
        ],
        [
            0x00, 0x00, 0x00, 0x00, 0xcd, 0xcc, 0xcc, 0x3e, 0x00, 0x00, 0x00, 0x00, 0xa3,
        ],
        [
            0xcd, 0xcc, 0x4c, 0x3e, 0x9a, 0x99, 0x99, 0xbe, 0x00, 0x00, 0x00, 0x00, 0xad,
        ],
    ];
    assert_eq!(found, expected);
}

#[test]
fn v2_drive() {
    // relay: heartbeat 7, to_legacy(1.5, 0.25)
    let bytes = [
        0xa5, 0x02, 0x00, 0x00, 0x00, 0x3f, 0x00, 0x00, 0x00, 0x3f, 0x00, 0x00, 0x00, 0x00, 0x07,
        0x01, 0x03,
    ];
    let frame = FrameV2::decode(&bytes).expect("a valid frame");
    assert_eq!(frame.counter, 7);
    assert_eq!(
        frame.flags,
        Flags {
            armed: true,
            estop: false
        }
    );
    assert_eq!(frame.encode(), bytes);
    assert_eq!(
        frame.values.check().expect("in range").targets(),
        Targets {
            steering: 2725,
            brake: 400,
            throttle: Throttle::Drive {
                code: 350,
                reverse: false
            }
        }
    );
}

