#[test]
fn up_timeout() {
    // the heartbeat stopped: braked, latched, fault 1, the last echo
    let bytes = [
        0xa5, 0x02, 0x01, 0x00, 0x63, 0x00, 0x01, 0x3e, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x80, 0x3f, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80, 0x3f, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0xff,
    ];
    let expected = Uplink {
        sequence: 0,
        echo: Some(99),
        mode: DriveMode::Stopped,
        switch: ModeSwitch::Computer,
        armed: false,
        estop: true,
        faults: 0x0001,
        steering: Some(f32::from_bits(0x00000000)),
        brake_position: Some(f32::from_bits(0x3f800000)),
        throttle_out: f32::from_bits(0x00000000),
        brake_out: f32::from_bits(0x3f800000),
        sticks: Sticks {
            throttle: f32::from_bits(0x00000000),
            steering: f32::from_bits(0x00000000),
            brake: true,
        },
    };
    assert_eq!(Uplink::decode(&bytes), Ok(expected));
    assert_eq!(expected.encode(), bytes);
}

